// handlerReturnVoidInline handles OpReturnVoid with ASM-inlined fast path.
TEXT ·handlerReturnVoidInline(SB), NOSPLIT, $32-0
	NO_LOCAL_POINTERS
	MOVD CTX_FRAME_POINTER(R19), R4
	MOVD CTX_BASE_FRAME_POINTER(R19), R5
	CMP  R5, R4
	BLE  rvi_fallback

	MOVD CTX_CSTACK_BASE(R19), R6
	MOVD $CALLFRAME_SIZE, R7
	MUL  R4, R7, R8
	ADD  R6, R8, R8

	MOVD CF_DEFERBASE(R8), R7
	MOVD CTX_DEFER_STACK_LEN(R19), R9
	CMP  R9, R7
	BNE  rvi_fallback

	SUB  $1, R4, R21
	MOVD $CALLFRAME_SIZE, R7
	MUL  R21, R7, R9
	ADD  R6, R9, R22

	MOVD CTX_ARENA_STR_IDX(R19), R3
	MOVD (CF_ARENA_SAVE+16)(R8), R5
	CMP  R3, R5
	BGE  rvi_str_clear_done
	MOVD CTX_ARENA_STR_SLAB(R19), R6
	LSL  $4, R5, R1
	ADD  R1, R6, R1
	LSL  $4, R3, R3
	ADD  R6, R3, R3

rvi_str_clear_loop:
	MOVD ZR, (R1)
	MOVD ZR, 8(R1)
	ADD  $16, R1, R1
	CMP  R3, R1
	BLT  rvi_str_clear_loop

rvi_str_clear_done:
	MOVD (CF_ARENA_SAVE+0)(R8), R1
	MOVD R1, CTX_ARENA_INT_IDX(R19)
	MOVD (CF_ARENA_SAVE+8)(R8), R1
	MOVD R1, CTX_ARENA_FLT_IDX(R19)
	MOVD (CF_ARENA_SAVE+16)(R8), R1
	MOVD R1, CTX_ARENA_STR_IDX(R19)
