	MOVD R1, CTX_ARENA_BOOL_IDX(R19)
	MOVD (CF_ARENA_SAVE+40)(R8), R1
	MOVD R1, CTX_ARENA_UINT_IDX(R19)
	MOVD (CF_ARENA_SAVE+96)(R8), R1
	MOVD R1, CTX_ARENA_SLICEBYTE_IDX(R19)

	MOVBU CF_HAS_GENERAL_ALLOC(R8), R3
	CBZ  R3, rvi_gen_clear_done
	BL   ·handlerCallInlineClearGeneralBank(SB)
	MOVD CTX_FRAME_POINTER(R19), R3
	SUB  $1, R3, R21
	MOVD CTX_CSTACK_BASE(R19), R6
	MOVD $CALLFRAME_SIZE, R7
	MUL  R21, R7, R9
	ADD  R6, R9, R22
rvi_gen_clear_done:

	MOVD R21, CTX_FRAME_POINTER(R19)

	MOVD CTX_ASM_CI_PTRS(R19), R1
	MOVD (R1)(R21<<3), R1
	MOVD R1, CTX_ASM_CALL_INFO_BASE(R19)

	MOVD CF_PROGRAM_COUNTER(R22), R20
	MOVD CF_REGS_INTS_PTR(R22), R23
	MOVD CF_REGS_FLOATS_PTR(R22), R24

	MOVD CF_REGS_STRINGS_PTR(R22), R1
	MOVD R1, CTX_STRINGS_BASE(R19)
	MOVD CF_REGS_UINTS_PTR(R22), R1
	MOVD R1, CTX_UINTS_BASE(R19)
	MOVD CF_REGS_BOOLS_PTR(R22), R1
	MOVD R1, CTX_BOOLS_BASE(R19)
	MOVD CF_REGS_SLICEBYTE_PTR(R22), R1
	MOVD R1, CTX_SLICES_BYTE_BASE(R19)
	MOVD CF_REGS_SLICESINT_PTR(R22), R1
	MOVD R1, CTX_SLICES_INT_BASE(R19)
	MOVD CF_REGS_SLICESFLOAT_PTR(R22), R1
	MOVD R1, CTX_SLICES_FLOAT_BASE(R19)
	MOVD CF_REGS_SLICESSTRING_PTR(R22), R1
	MOVD R1, CTX_SLICES_STRING_BASE(R19)
	MOVD CF_REGS_SLICESBOOL_PTR(R22), R1
	MOVD R1, CTX_SLICES_BOOL_BASE(R19)
	MOVD CF_REGS_SLICESUINT_PTR(R22), R1
	MOVD R1, CTX_SLICES_UINT_BASE(R19)
	MOVD CF_REGS_COMPLEX_PTR(R22), R1
	MOVD R1, CTX_COMPLEX_BASE(R19)

	MOVD CTX_DISPATCH_SAVES(R19), R1
	LSL  $6, R21, R7
	ADD  R1, R7, R1
	MOVD 0(R1), R22
	MOVD 8(R1), R21
	MOVD 16(R1), R26
	MOVD 24(R1), R7
	MOVD R7, CTX_FLT_CONSTS_BASE(R19)
	MOVD 32(R1), R7
	MOVD R7, CTX_STR_CONSTS_BASE(R19)
	MOVD 40(R1), R7
	MOVD R7, CTX_BOOL_CONSTS_BASE(R19)

	MOVD R22, CTX_CODE_BASE(R19)
	MOVD R21, CTX_CODE_LEN(R19)
	MOVD R20, CTX_PC(R19)
	MOVD R23, CTX_INTS_BASE(R19)
	MOVD R24, CTX_FLOATS_BASE(R19)
	MOVD R26, CTX_INT_CONSTS_BASE(R19)
	MOVD 0(RSP), R30
	ADD  $48, RSP
	DISPATCH_NEXT()

rvi_fallback:
	SUB  $1, R20, R20
	MOVD R20, CTX_PC(R19)
	MOVD $EXIT_RETURN_VOID, R0
	MOVD R0, CTX_EXIT_REASON(R19)
	MOVD R20, CTX_EXIT_PC(R19)
